sys_script_fix.script:
(function executeFixScript() {
    var tableName = "change_request";
    var fieldName = "category";

    // list of choices
    var newChoices = [
        { value: "CSA Configuration", label: "Cisco Secure Access", sequence: 400, inactive: false }
    ];

    // 1. Add category choice
    newChoices.forEach(function (choice) {
        var gr = new GlideRecord("sys_choice");
        gr.addQuery("name", tableName);
        gr.addQuery("element", fieldName);
        gr.addQuery("value", choice.value);
        gr.query();

        if (!gr.next()) {
            var newGr = new GlideRecord("sys_choice");
            newGr.initialize();
            newGr.name = tableName;
            newGr.element = fieldName;
            newGr.value = choice.value;
            newGr.label = choice.label;
            newGr.sequence = choice.sequence;
            newGr.inactive = choice.inactive;
            newGr.language = "en";
            newGr.insert();

            gs.log("Fix Script: Inserted choice " + choice.label);
        } else {
            gs.log("Fix Script: Choice " + choice.label + " already exists");
        }
    });

    // 2. Create text field: u_destination_address_1
    var fieldText = new GlideRecord("sys_dictionary");
    fieldText.addQuery("name", tableName);
    fieldText.addQuery("element", "u_destination_address");
    fieldText.query();
    if (!fieldText.next()) {
        var newField = new GlideRecord("sys_dictionary");
        newField.initialize();
        newField.name = tableName;
        newField.element = "u_destination_address";
        newField.internal_type = "string";
        newField.column_label = "Destination Address";
        newField.max_length = 255;
        newField.mandatory = false;
        newField.insert();
        gs.log("Fix Script: Created text field u_destination_address");
    } else {
        gs.log("Fix Script: Field u_destination_address already exists");
    }

    // 3. Create reference field: u_destination_list -> u_cisco_secure_access_destination_list
    var fieldRef = new GlideRecord("sys_dictionary");
    fieldRef.addQuery("name", tableName);
    fieldRef.addQuery("element", "u_destination_list");
    fieldRef.query();
    if (!fieldRef.next()) {
        var newRef = new GlideRecord("sys_dictionary");
        newRef.initialize();
        newRef.name = tableName;
        newRef.element = "u_destination_list";
        newRef.internal_type = "reference";
        newRef.reference = "u_cisco_secure_access_destination_list";
        newRef.column_label = "Destination List";
        newRef.mandatory = false;
        newRef.insert();
        gs.log("Fix Script: Created reference field u_destination_list");
    } else {
        gs.log("Fix Script: Field u_destination_list already exists");
    }

})();
